  feedIndustryProjectionReconciliationStatus:"distinct_series_scope_documented_not_directly_comparable",
   feedIndustryProjectionReconciliation2025:{differenceTon:594096,industryNeedSeriesTon:8844096,purchaseAbsorptionSeriesApproxTon:8250000,independentFarmerFeedNeedApproxTon:5360000,combinedRoundedFeedNeedApproxTon:13610000,nationalFeedNeedRoundedTon:13603000,combinedMinusNationalFeedNeedTon:7000,unit:"tonne/year",status:"scope_distinction_documented_numeric_rounding_gap_remains",note:"The 8.844096 Mt SiJagung reported industry-need projection differs by 594,096 t from the approximately 8.25 Mt factory purchase/absorption series. The latter plus approximately 5.36 Mt independent/self-mixing farmer demand gives 13.61 Mt, within 7,000 t of the rounded 13.603 Mt national feed need; this is a plausibility cross-check of rounded series, not proof of exact equivalence."},
